-- =====================================================================
-- GGLeague — Duel lobby
--
-- When a duel is accepted, a lobby is created for the two players:
--   * they agree on match details (series length, arena, host, time, note)
--   * both press "Ready"; the lobby locks and reveals the private-match
--     lobby name + password (generated by the system, so a result can be
--     tied to one specific match)
--   * a result can only be submitted once the lobby is locked
--
-- Clients get read-only access to their own lobby. All changes go through
-- SECURITY DEFINER functions, same model as the rest of the platform.
-- Run after 20261117000000_ggleague_schema.sql.
-- =====================================================================

create table public.duel_lobbies (
  duel_id          uuid primary key references public.duels(id) on delete cascade,
  best_of          int  not null default 1 check (best_of in (1, 3, 5)),
  arena            text not null default 'agree' check (arena in ('agree', 'standard', 'random')),
  host_id          uuid not null references public.profiles(id) on delete cascade,
  scheduled_at     timestamptz,                       -- null = play right now
  note             text check (note is null or char_length(note) <= 140),
  lobby_name       text not null,
  lobby_password   text not null,
  challenger_ready boolean not null default false,
  opponent_ready   boolean not null default false,
  locked_at        timestamptz,
  updated_by       uuid references public.profiles(id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

alter table public.duel_lobbies enable row level security;

create policy duel_lobbies_read on public.duel_lobbies for select using (
  exists (
    select 1 from public.duels d
     where d.id = duel_id and auth.uid() in (d.challenger_id, d.opponent_id)
  )
  or public.is_moderator()
);

revoke all on public.duel_lobbies from anon, authenticated;
grant select on public.duel_lobbies to authenticated;

-- ---------------------------------------------------------------------
-- Internal: unambiguous random codes (no 0/O, 1/I/L)
-- ---------------------------------------------------------------------
create or replace function public._gen_code(p_len int) returns text
language plpgsql volatile as $$
declare
  chars constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  out text := '';
  i int;
begin
  for i in 1 .. p_len loop
    out := out || substr(chars, 1 + floor(random() * length(chars))::int, 1);
  end loop;
  return out;
end $$;

-- ---------------------------------------------------------------------
-- Accepting a challenge now also opens the lobby
-- ---------------------------------------------------------------------
create or replace function public.respond_duel(p_duel uuid, p_accept boolean) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := public._require_uid(); v public.duels%rowtype;
begin
  select * into v from public.duels where id = p_duel for update;
  if not found then raise exception 'Duel not found'; end if;
  if v.opponent_id <> v_uid then raise exception 'Only the challenged player can respond'; end if;
  if v.status <> 'pending' then raise exception 'This challenge is no longer pending'; end if;

  update public.duels
     set status = case when p_accept then 'accepted' else 'declined' end, updated_at = now()
   where id = p_duel;

  if p_accept then
    insert into public.duel_lobbies (duel_id, host_id, lobby_name, lobby_password)
    values (p_duel, v.challenger_id, 'GG-' || public._gen_code(4), public._gen_code(4))
    on conflict (duel_id) do nothing;
  end if;
end $$;

-- ---------------------------------------------------------------------
-- Edit match details. Any change clears both ready flags so nobody
-- readies up against settings they have not seen.
-- ---------------------------------------------------------------------
create or replace function public.update_lobby(
  p_duel uuid, p_best_of int, p_arena text, p_host uuid,
  p_scheduled_at timestamptz, p_note text
) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := public._require_uid(); d public.duels%rowtype; l public.duel_lobbies%rowtype;
begin
  select * into d from public.duels where id = p_duel for update;
  if not found then raise exception 'Duel not found'; end if;
  if v_uid not in (d.challenger_id, d.opponent_id) then raise exception 'Not your duel'; end if;
  if d.status <> 'accepted' then raise exception 'This duel is not in the lobby stage'; end if;

  select * into l from public.duel_lobbies where duel_id = p_duel for update;
  if not found then raise exception 'Lobby not found'; end if;
  if l.locked_at is not null then raise exception 'The lobby is locked — settings can no longer change'; end if;

  if p_best_of not in (1, 3, 5) then raise exception 'Series must be best of 1, 3 or 5'; end if;
  if p_arena not in ('agree', 'standard', 'random') then raise exception 'Unknown arena choice'; end if;
  if p_host not in (d.challenger_id, d.opponent_id) then raise exception 'The host must be one of the two players'; end if;
  if p_scheduled_at is not null and p_scheduled_at < now() - interval '5 minutes' then
    raise exception 'Pick a time in the future, or leave it empty to play now';
  end if;
  if p_scheduled_at is not null and p_scheduled_at > now() + interval '14 days' then
    raise exception 'Schedule within the next 14 days';
  end if;

  update public.duel_lobbies
     set best_of = p_best_of, arena = p_arena, host_id = p_host,
         scheduled_at = p_scheduled_at,
         note = nullif(left(btrim(coalesce(p_note, '')), 140), ''),
         challenger_ready = false, opponent_ready = false,
         updated_by = v_uid, updated_at = now()
   where duel_id = p_duel;

  update public.duels set updated_at = now() where id = p_duel;
end $$;

-- ---------------------------------------------------------------------
-- Ready check. When both players are ready the lobby locks.
-- ---------------------------------------------------------------------
create or replace function public.set_ready(p_duel uuid, p_ready boolean) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := public._require_uid(); d public.duels%rowtype; l public.duel_lobbies%rowtype;
        v_c boolean; v_o boolean;
begin
  select * into d from public.duels where id = p_duel for update;
  if not found then raise exception 'Duel not found'; end if;
  if v_uid not in (d.challenger_id, d.opponent_id) then raise exception 'Not your duel'; end if;
  if d.status <> 'accepted' then raise exception 'This duel is not in the lobby stage'; end if;

  select * into l from public.duel_lobbies where duel_id = p_duel for update;
  if not found then raise exception 'Lobby not found'; end if;
  if l.locked_at is not null then raise exception 'The lobby is already locked'; end if;

  v_c := case when v_uid = d.challenger_id then coalesce(p_ready, false) else l.challenger_ready end;
  v_o := case when v_uid = d.opponent_id   then coalesce(p_ready, false) else l.opponent_ready   end;

  update public.duel_lobbies
     set challenger_ready = v_c, opponent_ready = v_o,
         locked_at = case when v_c and v_o then now() end,
         updated_at = now()
   where duel_id = p_duel;

  update public.duels set updated_at = now() where id = p_duel;
end $$;

-- ---------------------------------------------------------------------
-- Result submission: needs a locked lobby, and series scores must make
-- sense (best of 3/5 = games won; best of 1 = final goals).
-- Duels that predate the lobby feature (no lobby row) keep the old rules.
-- ---------------------------------------------------------------------
create or replace function public.report_duel(p_duel uuid, p_my_score int, p_opp_score int) returns void
language plpgsql security definer set search_path = public as $$
declare v_uid uuid := public._require_uid(); v public.duels%rowtype; l public.duel_lobbies%rowtype;
        v_need int; v_hi int; v_lo int;
begin
  if p_my_score is null or p_opp_score is null
     or p_my_score < 0 or p_opp_score < 0 or p_my_score > 99 or p_opp_score > 99 then
    raise exception 'Scores must be between 0 and 99';
  end if;
  if p_my_score = p_opp_score then raise exception 'Draws are not allowed — enter the final score'; end if;
  select * into v from public.duels where id = p_duel for update;
  if not found then raise exception 'Duel not found'; end if;
  if v_uid not in (v.challenger_id, v.opponent_id) then raise exception 'Not your duel'; end if;
  if not (v.status = 'accepted' or (v.status = 'awaiting_confirmation' and v.reported_by = v_uid)) then
    raise exception 'A result cannot be submitted for this duel right now';
  end if;

  select * into l from public.duel_lobbies where duel_id = p_duel;
  if found then
    if l.locked_at is null then
      raise exception 'Both players need to be ready in the lobby before a result can be submitted';
    end if;
    if l.best_of > 1 then
      v_need := (l.best_of + 1) / 2;
      v_hi := greatest(p_my_score, p_opp_score);
      v_lo := least(p_my_score, p_opp_score);
      if v_hi <> v_need or v_lo >= v_need then
        raise exception 'In a best of % the winner needs exactly % game wins (e.g. %–0 or %–%)',
          l.best_of, v_need, v_need, v_need, v_need - 1;
      end if;
    end if;
  end if;

  update public.duels
     set challenger_score = case when v.challenger_id = v_uid then p_my_score  else p_opp_score end,
         opponent_score   = case when v.challenger_id = v_uid then p_opp_score else p_my_score  end,
         reported_by = v_uid, reported_at = now(),
         status = 'awaiting_confirmation', updated_at = now()
   where id = p_duel;
end $$;

-- ---------------------------------------------------------------------
-- Privileges for the new functions (Supabase grants EXECUTE to client
-- roles by default, so revoke explicitly, then open only what is intended)
-- ---------------------------------------------------------------------
revoke execute on function public._gen_code(int) from public, anon, authenticated;
revoke execute on function public.update_lobby(uuid, int, text, uuid, timestamptz, text) from public, anon, authenticated;
revoke execute on function public.set_ready(uuid, boolean) from public, anon, authenticated;
grant execute on function public.update_lobby(uuid, int, text, uuid, timestamptz, text) to authenticated;
grant execute on function public.set_ready(uuid, boolean) to authenticated;
